{
  "headline": "FDA's records trace our supply to a plant classified OAI 2782 days after the shortage posting",
  "headline_cites": ["D6"],
  "sentences": [
    {
      "text": "FDA first posted the dexamethasone sodium phosphate shortage on 2019-02-08 and it remains current as of 2026-10-21.",
      "cites": ["E26", "E21"]
    },
    {
      "text": "A registered plant on our product labels, EUGIA PHARMA SPECIALITIES LIMITED (FEI 3008461619), received an OAI classification letter dated 2026-09-21, which is 2782 days after the shortage posting.",
      "cites": ["E19", "D6"]
    },
    {
      "text": "That plant had prior VAI inspections ending 2016-09-16, 2018-02-20, and 2018-12-14, and two recent OAI inspections ending 2024-02-02 and 2026-02-06.",
      "cites": ["E11", "E12", "E13", "E15", "E17"]
    },
    {
      "text": "A Warning Letter was issued to the same plant on 2024-08-15.",
      "cites": ["E18"]
    },
    {
      "text": "Other manufacturers on the FDA shortage list include Hikma Pharmaceuticals USA Inc., Fresenius Kabi USA LLC, Mylan Institutional, and Somerset Therapeutics LLC.",
      "cites": ["E22", "E23", "E24", "E25"]
    },
    {
      "text": "Corvale General holds 800 units with 18 days on hand and can spare 165 units while keeping two weeks of supply; Corvale East holds 216 units with 7 days on hand and would reach 12 days after the transfer.",
      "cites": ["D2", "D1", "D7"]
    },
    {
      "text": "The rule‑ranked option is to transfer 165 units from Corvale General to Corvale East, which requires a pharmacy director transfer request.",
      "cites": ["D7"]
    }
  ]
}
